annual_rent_cost = self.monthly_rent * 12

# Condition 1: Applicant has very low annual income
if self.annual_income <= 18000:
    return True

# Condition 2: Applicant has low to moderate annual income combined with other indicators of need
if self.annual_income <= 25000:
    is_vulnerable_employment = self.employment_status in ['unemployed', 'retired', 'student']

    has_high_rent_burden = False
    if self.annual_income > 0:
        # Check if annual rent cost exceeds 40% of annual income
        if (annual_rent_cost / self.annual_income) > 0.4:
            has_high_rent_burden = True
    elif self.monthly_rent > 0:
        # If annual income is 0 but there is monthly rent, it's a high burden
        has_high_rent_burden = True

    if is_vulnerable_employment or has_high_rent_burden:
        return True

# If none of the above conditions are met, the applicant is not eligible
return False
